// ============================================================================
// TYPES & INTERFACES
// ============================================================================

type ProductType =
  | 'PDF_EBOOK'
  | 'GOOGLE_DRIVE'
  | 'VIDEO_COURSE'
  | 'RESUME_TEMPLATE'
  | 'RESUME_BUNDLE'
  | 'STUDY_MATERIAL'
  | 'INTERVIEW_PREP'
  | 'SOFTWARE_ASSET'
  | 'OTHER';

type DeliveryType = 'PRIVATE_FILE' | 'GOOGLE_DRIVE_API' | 'AUTHORIZED_VIDEO';

type CareerTrack =
  | 'Fresher'
  | 'Experienced Professional'
  | 'IT'
  | 'Software Developer'
  | 'All Tracks';

interface Category {
  id: number;
  name: string;
  nameTa: string;
  slug: string;
  description: string;
  icon: string;
  isActive: boolean;
}

interface DigitalAssetInfo {
  id: number;
  assetName: string;
  deliveryType: DeliveryType;
  storageProvider: 'LOCAL_VAULT' | 'S3_PRIVATE' | 'GOOGLE_DRIVE' | 'VIMEO_PRIVATE';
  storageKeyOrFileId: string;
  mimeType: string;
  fileSizeLabel: string;
  videoLessons?: { id: number; title: string; duration: string; summary: string }[];
}

interface Product {
  id: number;
  categoryId: number;
  title: string;
  slug: string;
  shortDescription: string;
  detailedDescription: string;
  whatsIncluded: string[];
  productType: ProductType;
  careerTrack: CareerTrack;
  priceInr: number;
  discountPriceInr: number | null;
  isFree: boolean;
  coverGradient: string;
  badgeText: string;
  fileFormat: string;
  fileSizeLabel: string;
  videoDurationLabel?: string;
  compatibilityInfo: string;
  isFeatured: boolean;
  isBestseller: boolean;
  isPublished: boolean;
  isDemoProduct: boolean;
  salesCount: number;
  ratingAvg: number;
  reviewCount: number;
  createdAt: string;
  digitalAsset: DigitalAssetInfo;
  samplePreviewLines: string[];
}

interface ReviewItem {
  id: number;
  productId: number;
  userName: string;
  rating: number;
  comment: string;
  verifiedPurchase: boolean;
  createdAt: string;
}

interface Coupon {
  id: number;
  code: string;
  description: string;
  discountType: 'PERCENTAGE' | 'FIXED_INR';
  discountValue: number;
  minOrderAmountInr: number;
  maxDiscountInr: number;
  usedCount: number;
  isActive: boolean;
}

interface OrderRecord {
  id: number;
  orderNumber: string;
  receiptNumber: string;
  userId: number;
  customerName: string;
  customerEmail: string;
  items: {
    productId: number;
    title: string;
    productType: ProductType;
    pricePaidInr: number;
  }[];
  subtotalInr: number;
  discountInr: number;
  totalAmountInr: number;
  couponCode?: string;
  status: 'PENDING' | 'PAID' | 'FAILED' | 'REFUNDED';
  refundStatus: 'NONE' | 'REQUESTED' | 'REFUNDED';
  razorpayOrderId: string;
  razorpayPaymentId: string;
  razorpaySignature: string;
  paymentMethod: 'UPI' | 'CARD' | 'NETBANKING' | 'FREE_GRANT';
  signatureVerified: boolean;
  createdAt: string;
  paidAt: string;
}

interface DownloadAuditLog {
  id: number;
  productId: number;
  productTitle: string;
  assetName: string;
  signedUrlToken: string;
  expiresAt: string;
  downloadedAt: string;
}

interface SupportTicket {
  id: number;
  ticketNumber: string;
  name: string;
  email: string;
  subject: string;
  category: string;
  orderNumber: string;
  message: string;
  status: 'OPEN' | 'IN_PROGRESS' | 'RESOLVED';
  createdAt: string;
}

