// ============================================================================
// HELPER UTILITIES
// ============================================================================

function formatInr(amount: number): string {
  return new Intl.NumberFormat('en-IN', {
    style: 'currency',
    currency: 'INR',
    maximumFractionDigits: 0,
  }).format(amount);
}

function getEffectivePrice(product: Product): number {
  if (product.isFree) return 0;
  if (product.discountPriceInr !== null && product.discountPriceInr >= 0) {
    return product.discountPriceInr;
  }
  return product.priceInr;
}

function computeDemoHmacSignature(orderId: string, paymentId: string): string {
  // Deterministic hex digest simulation representing server-side HMAC-SHA256(orderId + "|" + paymentId, secret)
  const raw = `${orderId}|${paymentId}|RAZORPAY_SERVER_SECRET_2026`;
  let h1 = 0xdeadbeef ^ raw.length;
  let h2 = 0x41c6ce57 ^ raw.length;
  for (let i = 0; i < raw.length; i++) {
    const ch = raw.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  const part1 = (h1 >>> 0).toString(16).padStart(8, '0');
  const part2 = (h2 >>> 0).toString(16).padStart(8, '0');
  return `${part1}${part2}8f9a2c4e1b7d3a90${part2}${part1}6c5d4e3f2a1b0987`;
}

